INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','دليل عملي للزرايين العراقيين حول طرق مكافحة الآفات والأمراض في التريتيكله مع تحسين أداء نظام الري بالتنقيط. احصل على استراتيجيات واضحة لتعزيز صحة النبات وزيادة المردودية باستخدام حلول ري فعالة وموفرة للمياه.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
