INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Пешнамои муҳими идоракунии муштараки зараррасонандагон ва бемориҳо дар трициклэ</h2>\n<p>Тритикале (Triticale) маҳсули ҳибридӣ аст, ки аз таҳриби буғдуҷ ва ҷав бармеояд ва ба сабаби тобоварии баландтар дар муқобили хокишӣ ва сармо, дар минтақаҳои хунук ва минтақаҳо бо борони ноустувор хеле маъмул аст. Аммо яке аз мушкилоти асосии кишт кардани ин маҳсул, идоракунии самараи зараррасонандагон ва бемориҳо аст. Дар шароити нодурусти ободӣ, бемориҳои зангӣ, ба монанди занги трициклэ ва лаки баргҳо, метавонанд зуд паҳн шаванд. Бинобар ин, истифодаи усулҳои нав ободӣ, ба монанди шитобҳои сафедҷун ё қатра-ободӣ, метавонад шароити муҳитро ба фоидаи растани тағйир диҳад ва хатари гирифтан ба бемориҳоро кам кунад. Ин системаҳои нав бо тағйири динамикаи тар, монеаи пайдоишу ҷойҳои тар ва ноқис барои рушди микроорганизмҳои боҳашамкунанда мешаванд.</p>\n\n<>\n\n<h2>Таъсири ободии қатрагӣ ба шароити бунёди бемориҳо</h2>\n<h3>Идоракунии тарии хок ва кам кардани фишори зангҳо</h3>\n<p>Бисёр бемориҳои занги трициклэ, ба монанди занги зард (Puccinia hordei) ва латти кӯҳи (Septoria nodorum), дар шароити тарии баланд ва ҷӯйдашавии тӯлонӣ бар баргҳо рушд ва такрор меёбанд. Ободии қатрагӣ ва шитобҳои сафедҷун бо расонидани об мустақиман ба решаҳо ва кам кардани тарии асоси баргҳо, сатҳи гирифтор ба зангҳоро паст меорад. Ба ҳадди аксар, ободии ғарқобӣ ё боронӣ, ки ба сабаби паршонидани об ба таври якҷоя тарии нисбии ҳаворо баланд мебарад, метавонад шароити муфассалро барои спорулоизатсияи зангҳо эҷод кунад. Аз ин рӯ, дар системаҳои шитобҳои сафедҷун, ки об мустақиман аз дохили сӯзанҳо ба решаҳо мерасад, шароити муҳитӣ қатъан ба фоидаи саломати растани аст. Барои дарки беҳтар равандҳои ободии зерзаминӣ, ки ба реша ва хок таъсир мерасонад, шумо метавонед <a href="https://navar-abyari.ir/%d8%a2%d8%a8%db%8c%d8%a7%d8%b1%db%8c-%d8%b2%db%8c%d8%b1-%d8%b3%d8%b7%d8%ad%db%8c-%da%af%db%8c%d8%a7%d9%87%d8%a7%d9%86/">мақолаҳо дар бораи ободии зерзаминии растаниҳо</a> ҳарфаз куноед. Ин усулҳо тавассути нейтрал кардани рӯшноии nisбии дар қаблҳои болоии хок, аз ташкили плазмолиз ҳуҷайраҳо дар оқибати шиддати қуртқорӣ пешгирӣ мекунанд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-تریتیکاله-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="آفات و بیماری‌های تریتیکاله با آبیاری قطره‌ای - تصویر 1"/><figcaption>заҳоми эҳтимолӣ, бемориҳо, обёрӣ тавассути нафас, трийкал</figcaption></figure>\n\n<h3>Пешгирӣ аз рушди заҳомҳои хокӣ бо идоракунии дақиқи намӣ</h3>\n<p>Заҳомҳои хокӣ, ба монанди кӯршоми хокӣ ва кенаҳо, низ вобаста ба шартҳои намӣ мебошанд. Бо истифода аз системаҳои нафаси пайваста, намӣ маҳаллӣ дар атрофи реша нигоҳ дошта мешавад ва минтақаҳои хушкӣ дар атроф онро аз муҳоҷират ва аксбардории бисёр заҳомҳо пешгирӣ мекунад. Ин усул боиси кам шудани сироят ба заҳомҳои хокӣ дар муқоиса бо обёрии сатҳӣ ва кам шудани ҳоҷат ба истифодаи беҳудаи моддаҳои химиявӣ дар марҳилаҳои аввал мегарданд. Тақсимоти минтақаҳои хушкӣ ва намнок дар бозор ба таври як ҳисси муқовимати физикӣ-биологии муқовимат ба муҳоҷирони хокӣ амал мекунад. Инчунин, кам шудани намии сатҳӣ аз ташкили гелҳои часпак, ки паноҳгоҳи мувофиқ барои ҳуҷурдории баъзе заҳомҳо мебошанд, пешгирӣ мекунад. Бо ин наздикӣ, химиядермонӣ ба ҷои пумпакшии доимӣ ҳамчун як имконияти эҳтимолӣ ва ҳадафнок боқӣ мемонад. Кишондориҳо бояд аз гуногунии биологии баланди микрофлораи хок барои рақобат бо патогенҳо истифода баранд.</p>\n\n<>\n\n<h2>Заҳомҳои ҳашаротии фаъол дар трийкал ва усулҳои назорат</h2>\n<p>Баракчаҳо, монанди ҳашароти зӯронони трайскале ва афатиҳо, аз омилони асосии паҳншавии вирусҳо мебошанд. Ин зараррасонҳо бо истифода аз системаи обёрӣи тӯфлидӣ метавонанд аз назорати намии муҳити баргҳо, аз рӯшди популятсияҳои афатҳо ва зӯронон, ки дар шароити тар биёфтода беҳтар зараррасонӣ мекунанд, пешгирӣ кунанд. Инчунин бо татбиқи барномаи дақиқи обёрӣ, метавон аз ҷамъ шудани заргардҳо дар сатҳи баргҳо ва кам шудани қобилияти муҳофизатии гиёҳ пешгирӣ кард. Дар ин самт, шиносӣ бо ҳаҷми дарёфти мувофиқ ва принсипҳои бигзорӣ муҳимияти ду баробар меёбад; бинобар ин, омӯзиши мақолаҳо дар бораи истифодаи химикатҳо метавонад фоидаовар бошад. Ин идоракунии мутаваллотар интизофоти иловагии назорат пас аз зарардиҳиро кам мекунад. Бо ҳифзи мувозинати намӣ, гиёҳи трайскаале стрессро камтар таҷриба мекунад ва механизмҳои муҳофизатии биокимиёвии худро беҳтар фаъол мекунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-تریتیکاله-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="آفات و بیماری‌های تریتیکاله با آبیاری قطره‌ای - تصویر 2"/><figcaption>zararok, bīmori, obori pich-pich, triskale</figcaption></figure>\n\n<ul>\n  <li><strong>Ҳашароти зӯронони трайскале:</strong> Бо назорати намӣ ва пешгирӣ аз ҷамъ шудани тарии баргҳо, шароити ҳаракати ин зараррасон кам мешавад.</li>\n  <li><strong>Афатҳо:</strong> Намии баланди баргҳо боиси тезтарин зараррасони афатҳо мегардад; обёрӣи тӯфлидӣ ин хатарро кам мекунад.</li>\n  <li><strong>Курдони бадҳавои гандумӣ:</strong> Бо нигоҳдории намӣ дар поёни сатҳи хок, ҳаракати курдонҳои хокӣ ба сатҳ кам мешавад.</li>\n</ul>\n\n<>\n\n<h2>Тамоми анҷомдод барои беҳтар кардани обёри дорунаи триқалика</h2>\n<ol>\n  <li><strong>Мувозинат байни намӣ ва суръати афзоиш:</strong> Аз обёрди зиёдтар аз ҳад пайдо кунед. Суръати афзоиши триқалика бояд бо миқдори об таъминкунӣ мувофиқ бошад, то ки решаҳои растани фурсати мустақар кардани муҳофизатҳои табиии худро пайдо кунанд. Наомонҷаманӣ дар намӣ метавонад боиси пайдоишҳои микроскопӣ дар боддаи растани гардад ва ба ворид шудани осонтар паҳозунҳо (патогенҳо) имконият диҳад.</li>\n  <li><strong>Истифодаи ҷалбҳои тубӣ бо қатраҳои дақиқ:</strong> Дар триқалика, ки одатан бо фосилаҳои тарабонии кӯтоҳ (байни 30 то 50 сантиметр) боридан мешавад, ҷалбҳои тубӣ бо қутри 16 миллиметр ва андозаҳои 8 сантиметрӣ мувофиқ мебошанд. Ин ба шумо имкон медиҳад, ки танҳо хок дар атрофи реша намдор бошад. Интихоби дурусти қутри ҷалби тубӣ нақши асосӣ дар устувории ҷараёни обёрӣ мебошад.</li>\n  <li><strong>Нигоҳубини филтрҳо ва ҷалбҳо:</strong> Сабаби решаҳои чуқур ва ҳассоси триқалика, дар ҳолати банд шудан, он зуд ба фишор меояд. Филтрҳои мувофиқ ва шустаниши мунтазами ҷалбҳо аз банд шудан ва ба амал овардани шароити фишори хушкӣ дар маҳал пешгирӣ мекунанд, ки худ ба зиёд шудани ҳассосият ба бемориҳо оварда мерасонад. Дар ин соҳа, тадқиқот <a href="https://navar-abyari.ir/drip-tape-maintenance-costs/">мақолаҳо дар бораи хароҷоти нигоҳубини ҷалбҳои тубӣ</a> Шуморо меканад, ки бо қатраҳо ва лӯлаҳои мувофиқ шинос шавед.</li>\n  <li><strong>Назорати ҳарҳафтаномаи муҳити анбор:</strong> Ҳатто бо обёрӣ тавассути қатраҳо, назорати бёзун ба зардзанӣ баргҳо ё ҷамъшавии ҳашароти зараровар лозим аст. Бо муайян кардани зудмӯътамад, метавон аз паҳн шудани онҳо пешгирӣ кард. Назорат аз масофаи наздик бо кунҷҳои гуногун дақиқияти муайян карданро ба таври назаррас баланд мекунад.</li>\n</ol>\n\n<h2>Ҷавоб ба саволҳои мукаррар (FAQ)</h2>\n<table>\n  <thead>\n    <tr>\n      <th>Савол</th>\n      <th>Ҷавоб</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td>Оё нақоби тиб бевосита барои назорати зардзанӣи тритикале истифода мешавад?</td>\n      <td>Не, ба таври бевосита, аммо нақоби тиб бо коҳиши намии асосии барг ва нест кардани шартҳои муҳитии муносиб барои зангориҳо нақши муҳофизатии муҳимро иҷро мекунад. Ин намуди обёрӣ қисми барномаи идоракунии якҷоя аст, ки сарфариҳои табобатро ба таври назаррас кам мекунад.</td>\n    </tr>\n    <tr>\n      <td>Чӣ тавр аз гирифтор шудани системаи ирригатсияи таматтаб дар боғҳои трициколлев пешгирӣ кунем?</td>\n      <td>Трициколлев одатан бо донҳои калон напокӣ мешавад, бинобар ин, парвози моддаҳои зиёдатӣ ва зарраҳои калон аз системаи ирригатсияи таматтаб нодир аст. Аммо, истифодаи филтри мувофиқ ва шустушӯи муштараки система таъмин мекунад, ки қубурҳо бе мушкилот кор кунанд ва помпаҳо зер таъсир қарор нагиранд.</td>\n    </tr>\n    <tr>\n      <td>Оё дар фасли баҳор барои трициколлев ҳаҷми обдорӣ камтар бояд бошад?</td>\n      <td>Дар аксари минтақаҳо, трициколлев дар баҳор барои рафтроии биологӣ ниёз дорад. Аммо, дар минтақаҳои хушк, ирригатсияи таматтабӣ бо назорати дақиқ миқдори оби воридшуда имконият медиҳад, ки ғалав тадриҷан рафтроӣ кунад ва аз стресс аз сари шаби зиёдатии ниҳоӣ пешгирӣ шавад.</td>\n    </tr>\n    <tr>\n      <td>Оё асос кардани ирригатсияи таматтабӣ бо тӯҳифаи моддаҳои ғизоӣ ба идоракунии бемориҳо таъсир дорад?</td>\n      <td>Бале, ирригатсияи таматтабӣ имконият медиҳад, ки тӯҳифаи моддаҳои ғизоиро дар шакли маҳлул анҷом диҳед. Тайёр кардани ғалав бо моддаҳои ғизоии мувофиқ муҳофизати онро мустаҳкам мекунад ва дар муқобили зарароварҳо ва бемориҳо бартарии дорад. Дар бораи роҳи ҳисобкунии дақиқи моддаҳои ғизоӣ, шумо метавонед <a href="https://navar-abyari.ir/hosilnokiya-chukandari-qand-dar-gektar-omilhoi-muassisir/">мақолаҳоро дар бораи омилҳое, ки ба ҳосил шидат меоваранд, мусҳидат кунед.</a> мусҳидат кунед.</td>\n    </tr>\n  </tbody>\n</table>\n\n<h2>Хулоса</h2>\n<p>Дар охир, идоракунии зараррасонҳо ва бемориҳои тритикале тавассути системаҳои оварии қатрагӣ ва навбати тиб, на танҳо як усули ивазкунандаи оварии баронӣ мебошад, балки як стратегияи якҷоя барои сохутани муҳити мувофиқи афзоиш ва кам кардани зарар ба ҳосил аст. Бо идоракунии намии пастии барг ва кам кардани фишори зараррасонҳои хокӣ, эҳтимоли истеҳсоли маҳсулоти солимтар ва бо хатарпечии пастро зиёд мекунед. Бинобар ин, сармоягузорӣ ба системаҳои навбати тиб ва қатрагии сифатнок, дар ҳолки имконпазир аст, дар паҳлӯи омӯзиш ва назорати доимӣ, ба шумо кӯмак мекунад, то аз тритикале маҳсулоти муқовиматнок ва мувофиқаткунанда бо шароити иқлимӣ ба даст оваред. Умедворем, ки ин дастовард дар қарорҳои шумо муфид бошад ва барои омӯзиши бештар дар ин соҳа, мақолаҳои дигари мо дар navar-abyari.ir-ро пайгирӣ кунед. Истифодаи технологияҳои навкори кишоварӣ, қадами мустаҳкам ба самти паҳлукунии захираҳои табиӣ ва иқтисодиёти деҳот аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-تریتیکاله-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="آفات و بیماری‌های تریتیکاله با آبیاری قطره‌ای - تصویر 3"/><figcaption>зараррасонҳо ва бемориҳои ҳосил оварии қатрагӣ тритикале</figcaption></figure>\n\n<p><strong>Мақолаҳои пайванди:</strong> <a href="https://navar-abyari.ir/%D9%85%D9%82%D8%AF%D8%A7%D8%B1-%D8%A8%D8%B0%D8%B1-%DA%A9%D9%84%D8%B2%D8%A7-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">D985D982D8AFD8A7D8B1 D8A8D8B0D8B1 DAA9D984D8B2D8A7 D8AFD8B1 D987DAA9D8AAD8A7D8B1</a></p>','Идораъ кардани зарароварҳо ва бемориҳо дар чигирда бо системаҳои оборӣи тамчилӣ','Тритикале бародашт ба шароитҳои ноомулоиматии иқлимии бад ва дар минтақаҳои зиёд дар камбудии об ғалабогӣ мекунад. Аммо ин шароити махсус метавонад онро бар гурӯҳҳои мушаххаси зараровар ва бемориҳо нафосатнок кунад. Дар ин ҷо мо бо шумо таҳқиқ мекунем, ки чӣ тавр истифодаи системаҳои обёрӣ бо қатра ва банди тиббӣ на танҳо дар истифодаи бемории об, балки дар идора ва пешгирии зараровар ва бемориҳои тритикале самаранок хоҳад буд. Аз назорати намӣи хок то кам кардани фишори бемориҳои зинда, шумо дониши амиқтарро дар бораи ин таъсирҳо хоҳед гирифт. Дар ин пост дар navar-abyari.ir моро бо тафсилоти техникӣ ва амалӣ шинос мекунем, то метавонед беҳтарин таваққуфҳои чинишро ба анҷом расонед.','publish','closed','closed','idaror-kardani-zararovarho-chigirda-tamchil-obori',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
