INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима дар бораи киноа ва аҳамияти суръати ғарӣ</h2>\n<p>Кinoa (<em>Chenopodium quinoa</em>) ба ҳисоби яке аз дониҳои ҳосилнок барои муқовимат ба стресси муҳит, дар солҳои охир диққати кишоварони ҳиндиро ба худ ҷалб кардааст. Интихоби <strong>моддати боди киноа дар гектар</strong> дақиқ, омили асосӣ дар муайян кардани зичии ниҳоии растаниҳо ва дар натиҷа, ҳаҷми ҳосили дана мебошад. Гарчанде ин растани экзотикӣ аст, вале дар шароити оддии киш бо ороғи марказӣ, ба идоракунии дақиқи зичӣ ниёз дорад, то аз рақобати шадиди решаҳо ва камшавии андози дана пешгирӣ шавад. Бо дар назар доштани шароити мухталифи иқлимии Ҳинд, киноа махсусан дар минтақаҳои хушк ва нимхушк потенсиали баланд дорад, шарт он аст, ки идоракунии манбаъҳо бо дақиқат иҷро шавад. Хароҷҳои ноустувори суръати ғарии беҳтарин метавонад боиси камшавии шадиди истеҳсо ва зиёд шудани ҳаҷми сарфаи корҳои ниҳоли киш ва ҷамъоварӣ гардад. Бинобар ин, дарки амиқ аз механизмҳои афзоиш ва ниёзҳои обии ин растани, шарти асосии муваффақият мебошад.</p>\n\n<p>Истифодаи системҳои ороғи қатрагӣ ва махсусан танзими саби сабз дар гектар бо нӯбардҳои нӯбард, имконияти тақсими равшани намро фароҳам меорад, ки бевосита ба ғарии равшан таъсир мерасонад. Дар ин мақола, мо таҳқиқ мекунем, ки чӣ тавр бо ҳисоб кардани дурусти суръати ғарӣ, ҳамзамон бо ороғи иқтисодӣ, ба ҳосили баҳтарин расем. Инчунин, ба қисмҳои амиқтар аз физиологияи хок ва роҳи муоширати реша бо нӯбардҳои нӯбард дигар менамоем, то тасвири пурраи чархаи киб дар дастраси хонандон бошад.</p>\n\n<h2>Муҳимтарин нуктаҳо дар муайян кардани суръати ғарии киноа</h2>\n<h3>Фосилаи киш ва шумораи бутҳо дар метри мурабат</h3>\n<p>Муҳимтарин параметр дар ҳисобкунӣ <strong>Миқдори бехи кinoa дар хектар</strong>, фосилаи байни сатҳҳо ва фосилаи байни бехҳо аст. Нақши стандартии кишт, ки барои минтаҳаҳои хушк ва нимхушк тавсия дода мешавад, истифосилаи фосилаи сатҳӣ 50 то 60 сантиметр ва фосилаи бех 10 то 15 сантиметр мебошад. Бо ин андозҳо, зичии бехҳо дар ҳар метри квадратӣ тақрибан 168 то 200 бех хоҳад буд. Ин фосилагузорӣ имконро медиҳад, то доноти кinoa фазои кофӣ барои паҳншудаии тӯҷ ва гирифтани равшанӣи офтоб дошта бошанд. Дар ҳолати зиёд шудани зичӣ беш аз ҳадд, ботаниҳо рақобати равшанӣро оғоз карда, ба нозук шудани сабуку поин шудани сифати донот оварда мерасонанд. Аз тарафи дигар, зичии кам ба гум шудани қисме аз пурқуввати назарии маҳсул дар воҳиди сатҳ меоварад.</p>\n\n<p>Бо назардошти дарҷадони 85 то 95 фоизии бехи кinoa бояд суръати бехпаҳкӣро чунин танзим кунед, ки шумораи ниҳоии бехҳои боқимонда ба нақши кишт мувофиқат кунад. Ба таври миёна, барои кишт бо маҷмӯаҳои дақиқ, суръати бехпаҳкӣ 4 то 5 килограмм дар хектар одатан ба зичии ҳасобшаванда оварда мерасонад. Агар аз кишти дастӣ ё пахшкунандаҳои оддитар истифода баред, шояд ба 6 то 7 килограмм лозим бошад, то пӯшиши баробарӣ эҷод шавад. Ҳисоби дақиқи ин миқдорҳо таваҷҷуҳ ба вазни ҳазор дони (THS)-ро талаб мекунад, ки дар бехҳои интихобшуда фарқ мекунад ва мустақиман ба ҳаҷми физикии бехи лозима барои ҳар хектар таъсири мерасонад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-کینوا-در-هکتار-راهنمای-جامع-تصویر-شاخص.webp" alt="مقدار بذر کینوا در هکتار: راهنمای جامع - تصویر 1"/><figcaption>суръати бех паҳкӣ дар хектар барои ҳосили кinoa</figcaption></figure>\n\n\n\n<h3>Таъсири сифати бех ва пеш аз таҳлил</h3>\n<p>Сифати бургӣ дувор аст. Қабл аз муайян кардани ниҳоии нурҳайи бургӣ, ҳатман таҷрибаи хушкшавӣ ва қудрати шӯруъ анҷом диҳед. Агар хушкшавӣ 90 фоиз бошад, ҳисобҳо мувофиқ ба ин фоиз танзим карда мешаванд. Инчунин, ҳарорати муҳит ҳангоми кортӣ бояд зиёда аз 15 дараҷаи Селсӣ бошад, то хатари яхбозии ғалъа кам шавад ва нурҳайи бургӣ ниёз ба ҷуброни камбудиҳои ибтидоӣ на дошта бошад. Бургиҳое, ки синнашон баланд аст ё нодуруст нигоҳ дошта шудаанд, ҳатто бо нурҳайи баландтари бургӣ метавонанд наметавонанд фарогирии якхела созанд, бинобар ин интихоби бургии наву сифатнок ва боварӣбахш ҳамеша тавсия мешавад. Таҷрибаи пешакӣ бояд дар шартҳои муқобил ба муҳити кортӣ анҷом дода шавад, то натиҷаҳои боварӣбахштар ба даст ояд.</p>\n\n<h2>Намуднокунӣ дар ирригатсияи нақди тибӣ бо кинва</h2>\n<p>Яке аз муроққобатҳои асосии корти кинва дар минтаҳои камобӣ идоракунии истифодаи об аст. Дар овардани <a href="https://navar-abyari.ir/%d9%86%d8%ad%d9%88%d9%87-%d8%a7%d9%81%d8%b2%d8%a7%db%8c%d8%b4-%da%a9%d8%a7%d8%b1%d8%a7%db%8c%db%8c-%d9%88-%d8%a8%d9%87%d8%b1%d9%87%d9%88%d8%b1%db%8c-%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c/">Руҳурди зиёд кардани самаранокии ва бартарии нақди тиб</a> метавонад истифодаи обро то 30 фоиз кам кунад. Дар ин система, нақди тиб бешубҳа дар хатҳои кортӣ ҷойгир мешавад ва об танҳо ба минтакаи решаҳо (Root Zone) мерасад. Ин боиси он мегардад, ки баъдиҳо бо зичии баланд дар як воҳиди сатҳ, метавонанд решаҳои худро дар чуқуриҳои гуногун паҳн кунанд, бидуни рақобати шиддати мушоҳидаи рақобат барои намнокӣ. Ин усули ирригатсия инчунин кӯмак мекунад, ки дарахтони ҳашарзан бошад кам шаванд ва энергияи баъдиҳӣ барои рушди сабзӣ ва истеҳсоли дон топишад.</p>\n\n<h3>Ҷустии шартҳои оли бо нақдпур</h3>\n<p>Барои пешгирӣ аз бемориҳои зангоришӣ дар зичии баланд, муҳим аст, ки шароити алӣ бо раванди обёрӣ мутобиқ бошад. Аз шароити алӣ бо тамдиқ дар анбор метавон ифода кард, то намдории хок бо давомнокии дақиқ идора карда шавад. Тағйироти шадиди намдорӣ метавонад боиси шикасти марҳилавӣ (Stagebreak) дар рушди рӯи кинава гардад ва дар натиҷа ҳосилнокии дунбашро кам кунад. Назокии мунтазами сатҳи намдории хок дар чуъни 10 то 20 см калиди муваффақӣ аст, ки бояд дар идоракунии рӯзона риоя шавад. Истифодаи сенсорҳои хокӣ низ метавонад дақиқии ин идоракуниро баланд бардорад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-کینوا-در-هکتار-راهنمای-جامع-کاربرد-عملی.webp" alt="مقدار بذر کینوا در هکتار: راهنمای جامع - تصویر 2"/><figcaption>нишеби кинава барои гектар</figcaption></figure>\n\n\n\n<h2>Нуқтаҳои амалӣ барои беҳтар кардани кӯтиш</h2>\n<ul>\n<li><strong>Омода кардани бинии буб:</strong> Бинии буб бояд сабук ва бепул бошад, то паҳнокунии баробари бубҳои хурди кинава имконпазир бошад. Ҳар гуна кобҳои бузурги хокӣ метавонанд суръати паҳнокунии ва фаъолияти рӯиро боздорад. Оператсияи кӯтиш пеш аз нишастани буб бояд бо дақиқ иҷро карда шавад, то сатҳи замин ҳамвор ва бе қабис бошад.</li>\n<li><strong>Интихоби вақти кӯтиш:</strong> Беҳтарин вақти нишастани кинава дар нишеби аввал то миёнаи баҳор аст. Бо вуҷуди ин, дар минтақаҳои кӯҳистон, кӯтиш бояд каме дер карда шавад, то хатар бақиммаи ях шуда будан бардорад. Дери кардани кӯтиш одатан ба кам кардани зиёдӣ (шикарди камтари буб дар гектар) ниёз дорад, зеро давраи пухтани дунба кӯтоҳтар мешавад. Мутобиқ будани вақти нишастан бо пешгӯии обӣ аҳамияти баланд дорад.</li>\n<li><strong>Идоракунии зиёдӣ:</strong> Агар дидаед, ки растаниҳо зиёдатӣ ва чангҳо ба ҳам ҷойгирифтаанд, ба ҷои гирифтани боҳор (ки арзон нест), метавонед дар марҳилаи намоиш бо кам кардани ҳисси бӯғоти сол оғозкунии мушкилро пешгирангӣ кунед. Асоси идоракунии зичӣ таҳияи нақша пеш аз рушд аст, на ислоҳи пас аз афзоиш.</li>\n<li><strong>Оросиши дақиқ:</strong> аз <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d8%b9%d8%af%d8%b3-%d8%a2%d8%a8%db%8c-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Ҳаҷми истеҳсоли лӯбумони обӣ дар гектар: Рӯзномаи умумии афзайиши хосилорӣ</a> Метавон алгоритмҳои монанд барои ҳосилпакии дақиқро ёд гирифт; кинва низ хамин тавр ба тақсими дақиқи об ҳассос аст. принсипҳои идоракунии об дар гӯбӣ ва ғаллакунандаҳо ба кинва низ мумкин аст.</li>\n</ul>\n\n<h2>Саволҳои маъмул (FAQ)</h2>\n<h3>1. Оё метавон кинваро дар шароити оросиши моғонӣ партофту?</h3>\n<p>Бале, аммо дар ин ҳолат ҳисси бӯғот бояд каме зиёд шавад (тақрибан 6-8 килограмм дар гектар), то ки пӯшиши пурра таъмин карда шавад, зеро хатари шикасти партофтӣ аз сабаби боришотҳои пайдарпаӣ ва фурӯ рафти муваққати хок бартар аст. Дар ин шартҳо, дренажи хок низ бояд дида шуд, то ки вайрониши рутубат пешгирӣ карда шавад.</p>\n\n<h3>2. Фосилаи мувофиқ барои лойирип дар киновия кадом аст?</h3>\n<p>Фосила байни лойирип бояд бо фосилаи сатҳҳои киновия мувофиқат кунад. Одатан, ҳар 30 то 50 сантиметр як лойирип ҷойгир карда мешавад. истифодаи системаҳои барои истифодаи лойирип барои обёрӣ дар наздикии ҳарфзорӣ метавонад дар коҳиши истеҳсоли нусха ва зиёд кардани умри система муфид бошад, гарчанде ки барои дарёфти ҳосил, ҷойгиршавии дақиқ дар сатҳ авлотия дорад. Интихоби намуди лойирип бояд асосан бар фишори об ва сарпиёни лозима дар ҳар гектар анҷом шавад.</p>\n\n<h3>3. Чаро ҳосили кинваи ман бо кишт дар қасри ҳамсоя фарқ дорад?</h3>\n<p>Оҳистаи асосии фарқият дар <strong>миқдори бобуки кинвай дар гектар</strong> ё сифати бобуки ибтидоӣ аст. Инчунин фарқият дар намуди хок ва дараҷаи чуқурӣ бобуки (ки набояд аз 2 то 3 сантиметр зиёд бошад) омиле муҳим аст. Бобуки чуқуртари шуда ба сари коҳиш дорад ва зичии ниҳоӣ камтар месозад. Инчунин, фарқият дар сатҳи гуногун ва тағозии реша метавонад ба ҳосили ниҳоӣ таъсир расонад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-کینوا-در-هکتار-راهنمای-جامع-جزئیات-فنی.webp" alt="مقدار بذر کینوا در هکتار: راهنمای جامع - تصویر 3"/><figcaption>сифати бобукӣ ба гектар бобуки кинвай</figcaption></figure>\n\n\n\n<h2>Хулоса</h2>\n<p>Муайяна <strong>Микдори тоҳукҳои кинва дар ҳектар</strong> Ин раванди динамикӣ аст, ки вобаста ба сифати тоҳук, шароити хок ва системаи интихобии обёрӣ танзим карда мешавад. Барои дастёби беҳтарин самаранокии иқтисодӣ дар шароити Ирон (ё Тоҷикистон, агар мақсад ҷумҳурӣ бошад, вале матни асл Иронеро ном бурдааст, бинобар ин мунтақиладири Иронро нигоҳ медорем), омезиши суръати тоҳукдории 4 то 5 килограмм дар ҳектар бо системаи обёрӣ сатҳгирӣ ё нӯри тибор (drip or tape) бо дақиқи баланд беҳтарин интихоб аст. Ин равиш на танҳо аз талафоти об пешгирӣ мекунад, балки бо эҷоди зиёднокӣ-и оптималӣ, рақобати рӯишӣ-ро хориҷ мекунад ва сифати доноро кафолат мекунад. Кӯрбонҳое, ки дар ҷустуҷӯи зиёднокӣ-и самаранокият ҳастанд, бояд ҳамеша ба идоракунии дақиқи кӯдакҳои тоҳук ва нақши кӯшиш доданд, то сармоягузории худро дар донҳои кинвро бо самаранокии устувор баргардонида кунанд.</p>\n\n<p>Барои фаҳмиши амиқтарин аз таъсири хок ба системаҳои обёрӣ, таҳқиқоти мавзӯи <a href="https://navar-abyari.ir/ahamiyati-bozinsii-zamin-baroi-navori-tip-va-nayii-poli/">аҳамияти барқароркунии замин барои нӯри тибор ва нӯри поли</a> тавсия карда мешавад. Шумора, барои нигоҳубини дурусти таҷҳизот, ба дастурали <a href="https://navar-abyari.ir/negahdorii-navori-tip-harajat/">нигоҳубини нӯри тибори гармидиҳӣ</a> назар карда шавад, то дар фаслҳои сард аз зарари расидани ба системаи обёрӣ пешгирӣ карда шавад.</p>\n\n<p><strong>Мақолаҳои ассотсатсияӣ:</strong> Фазои ҷойгиршавии татум дар һектар</p>','Миқдори бӯди қино дар гектар: Роҳнамои мукаммал','Ошноӣ бо беҳтарин суръати тухмронии киноа барои фароҳан дар Эрон, таъсири масофаи сатҳҳо ба ҳосилии ниҳоӣ ва дастурамали пурраи озуи дақиқ бо системаи нафаскашӣ.','publish','closed','closed','miqdomi-budi-qino-dar-hektar-rohnamoyi-mukammal',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
